insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_61_v1'
from (values
('127.401.d.1.A',3,'A physics student notices that a heavier cart rolls farther down a ramp. The best next step is to:','["turn the observation into a testable question", "decide the answer without testing", "ignore the result", "copy a classmate''s data"]'::jsonb,0,'Science begins with questions from observations.','original'),
('127.401.d.1.A',4,'Which problem statement for an engineering team is the most testable?','["Carts are fun to roll.", "How does ramp angle change the speed of a cart at the bottom?", "Ramps are interesting.", "Is physics hard?"]'::jsonb,1,'A testable question names variables that can be measured.','original'),
('127.401.d.1.B',3,'An investigation that measures one variable while holding the others constant is a:','["story", "guess", "controlled experiment", "opinion poll"]'::jsonb,2,'Controls isolate the effect of one variable.','original'),
('127.401.d.1.B',4,'A comparative investigation of two spring brands should keep which factor the same?','["the color", "the final stretch", "the brand", "the mass hung from each spring"]'::jsonb,3,'Everything except the tested variable stays constant.','original'),
('127.401.d.1.C',3,'Before a lab that uses a moving cart and a falling mass, students should put on:','["safety goggles", "gloves with loose cuffs", "earbuds", "sandals"]'::jsonb,0,'Eye protection guards against flying parts.','original'),
('127.401.d.1.C',4,'Long hair and loose clothing near a rotating motor should be:','["left loose for comfort", "secured before the motor starts", "ignored", "tucked in after it starts"]'::jsonb,1,'Loose items can catch in moving parts.','original'),
('127.401.d.1.D',3,'An ammeter is used to measure:','["voltage", "mass", "electric current", "time"]'::jsonb,2,'Ammeters measure current in amperes.','original'),
('127.401.d.1.D',4,'To measure the mass of a small cart accurately, a student should use a:','["ruler", "thermometer", "stopwatch", "balance"]'::jsonb,3,'Balances measure mass.','original'),
('127.401.d.1.E',3,'In SI units, force is measured in:','["newtons", "pounds", "gallons", "miles"]'::jsonb,0,'The newton is the SI unit of force.','original'),
('127.401.d.1.E',4,'A length recorded as 250 centimeters equals how many meters in SI?','["250", "2.5", "25", "0.25"]'::jsonb,1,'100 centimeters make 1 meter.','original'),
('127.401.d.1.F',3,'Data are best recorded during a lab in a:','["text to a friend", "memory", "bound notebook or engineering log", "loose napkin"]'::jsonb,2,'Notebooks keep a dated, permanent record.','original'),
('127.401.d.1.F',4,'Qualitative data differ from quantitative data because they are:','["always graphs", "more accurate", "always numbers", "descriptions rather than measurements"]'::jsonb,3,'Qualitative data describe qualities.','original'),
('127.401.d.1.G',4,'A computer simulation of a falling object is a:','["mathematical model", "physical copy of the object", "conclusion", "hypothesis"]'::jsonb,0,'Simulations use equations to model behavior.','original'),
('127.401.d.1.H',4,'Newton''s second law, written F = ma, is an example of a scientific:','["theory of everything", "law", "opinion", "hypothesis"]'::jsonb,1,'Laws describe relationships, often mathematically.','original'),
('127.401.d.2.A',3,'One limitation of a small-scale model is that it may not:','["be drawn", "be built", "behave exactly like the full-size system", "be measured"]'::jsonb,2,'Scaling can change real behavior.','original'),
('127.401.d.2.A',4,'A model of a river that ignores friction would most likely give results that are:','["exact", "unrelated", "too slow", "too fast compared with the real river"]'::jsonb,3,'Leaving out friction overestimates speed.','original'),
('127.401.d.2.B',3,'A trend that increases steadily on a graph shows a:','["positive relationship between the variables", "negative relationship", "mistake", "no data"]'::jsonb,0,'Both variables rise together.','original'),
('127.401.d.2.B',4,'Four lab trials give times of 2.1, 2.0, 2.2, and 2.1 s. The mean time is:','["2.2 s", "2.1 s", "8.4 s", "2.0 s"]'::jsonb,1,'Sum 8.4 divided by 4 is 2.1.','original'),
('127.401.d.2.C',3,'A car travels 120 meters in 6 seconds at constant speed. Its speed is:','["126 m/s", "0.05 m/s", "20 m/s", "720 m/s"]'::jsonb,2,'120 divided by 6 equals 20.','original'),
('127.401.d.2.C',4,'If a force of 12 N acts on a 3 kg cart on a smooth surface, its acceleration is:','["36 m/s²", "9 m/s²", "0.25 m/s²", "4 m/s²"]'::jsonb,3,'a = F/m = 12/3 = 4.','original'),
('127.401.d.2.D',3,'After testing a design that failed, an engineer should:','["analyze the cause and improve the design", "blame the tools", "hide the result", "stop forever"]'::jsonb,0,'Failure data guide improvement.','original'),
('127.401.d.2.D',4,'Optimizing a design means making it:','["the largest", "best for the stated goals within the constraints", "the cheapest only", "the heaviest"]'::jsonb,1,'Optimization balances goals and limits.','original'),
('127.401.d.3.A',3,'A good scientific explanation is supported by:','["rumor", "popularity", "data and models", "opinion alone"]'::jsonb,2,'Claims need evidence.','original'),
('127.401.d.3.A',4,'If data from three trials disagree with a proposed solution, the team should:','["stop the project", "discard the data", "repeat the claim louder", "revise the explanation to fit the data"]'::jsonb,3,'Evidence outranks the first idea.','original'),
('127.401.d.3.B',3,'When a team shares its results, a clear way to communicate is to use:','["labeled tables and graphs", "jokes only", "silence", "unlabeled numbers"]'::jsonb,0,'Visuals with labels clarify results.','original'),
('127.401.d.3.B',4,'A team report should explain not only what happened but also:','["who finished first", "how the data support the conclusion", "the weather", "what snacks were eaten"]'::jsonb,1,'Conclusions must link to evidence.','original'),
('127.401.d.3.C',3,'In a respectful scientific argument, a student responds to a different view by:','["walking away", "insulting the speaker", "using evidence to support or question it", "shouting"]'::jsonb,2,'Argument relies on evidence and respect.','original'),
('127.401.d.3.C',4,'A claim, evidence, and reasoning together make up a:','["data table", "hypothesis only", "opinion", "scientific argument"]'::jsonb,3,'Strong arguments link claim to evidence by reasoning.','original'),
('127.401.d.4.A',3,'To critique a published explanation, a student should check whether the:','["conclusion is supported by the evidence", "author is famous", "paper is long", "title is short"]'::jsonb,0,'Evaluate evidence, not fame.','original'),
('127.401.d.4.A',4,'A solution that works only under ideal conditions has a weakness in its:','["title", "real-world reliability", "price tag only", "color"]'::jsonb,1,'Ideal results may not hold in practice.','original'),
('127.401.d.4.B',3,'Research on the nature of light changed how scientists think because new findings led to:','["no change", "fewer questions", "revised theories", "silence"]'::jsonb,2,'New evidence changes thought.','original'),
('127.401.d.4.B',4,'The discovery that the atom has a nucleus changed physics because it:','["proved matter is not real", "removed electrons", "ended all research", "replaced the earlier model of the atom"]'::jsonb,3,'New data replaced the older model.','original'),
('127.401.d.4.C',3,'Students can learn how engineers work by visiting a museum, a library, or:','["a professional engineering organization", "a random chat", "a game arcade", "a candy store"]'::jsonb,0,'Professional groups share career knowledge.','original'),
('127.401.d.4.C',4,'A reliable source for a physics project is a:','["anonymous post", "peer-reviewed article or textbook", "rumor", "advertisement"]'::jsonb,1,'Reviewed sources are more trustworthy.','original'),
('127.401.d.5.A',3,'An engineering need can be identified by talking with:','["only the builder", "no one", "the people who will use the solution", "only a friend"]'::jsonb,2,'Users know the problem best.','original'),
('127.401.d.5.A',4,'Which is the better need statement?','["Jars exist.", "Make a nice jar.", "People like kitchens.", "Elderly users need a jar opener that works with limited grip strength."]'::jsonb,3,'A need names who, what, and why.','original'),
('127.401.d.5.B',3,'An engineering proposal should list the plan, the people, and the:','["resources and schedule", "weather", "jokes", "slogans"]'::jsonb,0,'Proposals cover resources and time.','original'),
('127.401.d.5.B',4,'A proposal that includes a budget helps the team to:','["hide risks", "stay within limits on cost", "avoid testing", "skip planning"]'::jsonb,1,'Budgets are constraints.','original'),
('127.401.d.5.C',3,'After a solution is built, the team should analyze it by:','["selling it", "hiding it", "testing it against the criteria", "admiring it"]'::jsonb,2,'Testing checks that criteria are met.','original'),
('127.401.d.5.C',4,'A bridge model holds 5 kg but the goal was 8 kg. The best suggestion is to:','["declare success", "change the goal secretly", "remove the load", "strengthen the weakest members and retest"]'::jsonb,3,'Improve based on results.','original'),
('127.401.d.5.D',3,'A trade-off in design means gaining one benefit while:','["giving up something else", "ending the project", "gaining nothing", "losing nothing"]'::jsonb,0,'Design choices trade one factor for another.','original'),
('127.401.d.5.D',4,'Using a stronger but heavier material in a bicycle frame creates a trade-off between strength and:','["age", "weight", "name", "color"]'::jsonb,1,'Strength often costs weight.','original'),
('127.401.d.6.A',3,'A hypothesis in physics must be:','["a feeling", "unchangeable", "testable with evidence", "a fact already"]'::jsonb,2,'Hypotheses are testable predictions.','original'),
('127.401.d.6.A',4,'Which is a testable hypothesis?','["Carts are pretty.", "Speed is cool.", "Ramps are good.", "If the ramp angle doubles, the cart''s final speed will increase."]'::jsonb,3,'It predicts a measurable change.','original'),
('127.401.d.6.B',3,'A sound wave and a ball thrown through the air differ because the wave:','["transfers energy without moving matter along", "has no energy", "moves the whole medium forward", "is made of balls"]'::jsonb,0,'Waves transfer energy.','original'),
('127.401.d.6.B',4,'Light shows both particle and wave behavior, which is called:','["particle law", "wave-particle duality", "double slit law", "wave fission"]'::jsonb,1,'Light behaves as both.','original'),
('127.401.d.6.C',3,'When designing an investigation, a student should first decide what to:','["wear", "eat", "measure and how", "buy"]'::jsonb,2,'Procedures define measurements.','original'),
('127.401.d.6.C',4,'A procedure is reliable if another team can:','["only guess the steps", "not follow it", "skip steps", "repeat it and get similar results"]'::jsonb,3,'Repeatability is key.','original'),
('127.401.d.6.D',3,'A micrometer is more precise than a ruler for measuring the:','["thickness of a thin wire", "width of a hall", "length of a room", "height of a door"]'::jsonb,0,'Micrometers measure small distances precisely.','original'),
('127.401.d.6.D',4,'To reduce error when reading a ruler, a student should view the scale:','["from the side", "straight on to avoid parallax", "with one eye shut from far away", "quickly"]'::jsonb,1,'Viewing at an angle causes parallax error.','original'),
('127.401.d.6.E',3,'Every measurement has some:','["perfection", "certainty", "uncertainty", "magic"]'::jsonb,2,'No measurement is exact.','original'),
('127.401.d.6.E',4,'A scale reading 4.5 kg with an uncertainty of ±0.1 kg means the true value is likely between:','["4.5 and 5.5 kg", "0 and 4.5 kg", "4.0 and 5.0 kg", "4.4 and 4.6 kg"]'::jsonb,3,'Add and subtract the uncertainty.','original'),
('127.401.d.6.F',3,'Plotting distance against time and finding the slope gives the:','["speed", "mass", "density", "energy"]'::jsonb,0,'Slope of a distance-time graph is speed.','original'),
('127.401.d.6.F',4,'A straight line through the origin on a graph of force versus acceleration shows that:','["force is zero", "force is proportional to acceleration", "force is constant", "they are unrelated"]'::jsonb,1,'Direct proportion gives a line through the origin.','original'),
('127.401.d.6.G',3,'A lab report conclusion should state whether the data:','["are pretty", "are long", "support the hypothesis", "are new"]'::jsonb,2,'Conclusions tie to the hypothesis.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_61_v1'
from (values
('127.401.d.6.G',4,'A conclusion that mentions sources of error shows that the author:','["ignored the data", "did the work wrong", "wasted time", "considered how reliable the results are"]'::jsonb,3,'Error analysis strengthens a report.','original'),
('127.401.d.7.A',3,'Safety information for a laboratory machine can be found in the:','["operator manual and safety data sheet", "game guide", "calendar", "menu"]'::jsonb,0,'Manuals give hazards and procedures.','original'),
('127.401.d.7.A',4,'Before using unfamiliar equipment, a student should:','["start at full power", "read the instructions and get approval", "ask a friend to try", "guess the controls"]'::jsonb,1,'Know the equipment first.','original'),
('127.401.d.7.B',3,'Used chemicals and batteries in a lab should be:','["thrown in the trash", "left on the bench", "disposed of following the posted procedure", "poured down the drain"]'::jsonb,2,'Hazardous waste needs special handling.','original'),
('127.401.d.7.B',4,'A safety data sheet tells a lab worker about a material''s hazards and how to:','["paint it", "name it", "buy it", "handle and dispose of it safely"]'::jsonb,3,'SDS lists handling and disposal.','original'),
('127.401.d.8.A',3,'For constant acceleration, the equation v = v0 + at relates final velocity to initial velocity, acceleration, and:','["time", "mass", "energy", "force"]'::jsonb,0,'The variable t is time.','original'),
('127.401.d.8.A',4,'A car starts at rest and accelerates at 3 m/s² for 5 s. Its final velocity is:','["75 m/s", "15 m/s", "8 m/s", "0.6 m/s"]'::jsonb,1,'v = 0 + 3 x 5 = 15.','original'),
('127.401.d.8.B',3,'A vector quantity has both magnitude and:','["color", "price", "direction", "name"]'::jsonb,2,'Vectors need direction.','original'),
('127.401.d.8.B',4,'Which of these is a scalar?','["displacement", "velocity", "acceleration", "speed"]'::jsonb,3,'Speed has no direction.','original'),
('127.401.d.8.C',3,'A runner goes 100 m east then 40 m west. Her displacement is:','["60 m east", "100 m east", "140 m east", "40 m west"]'::jsonb,0,'100 minus 40 is 60 east.','original'),
('127.401.d.8.C',4,'The same runner''s total distance traveled is:','["100 m", "140 m", "40 m", "60 m"]'::jsonb,1,'Distance adds all path lengths.','original'),
('127.401.d.8.D',3,'A ball is dropped from rest. After 2 s, ignoring air resistance (g = 10 m/s²), its velocity is about:','["5 m/s", "40 m/s", "20 m/s", "10 m/s"]'::jsonb,2,'v = gt = 20.','original'),
('127.401.d.8.D',4,'A ball dropped from rest falls for 3 s (g = 10 m/s²). It falls about:','["90 m", "30 m", "15 m", "45 m"]'::jsonb,3,'d = 1/2 x 10 x 9 = 45.','original'),
('127.401.d.8.E',3,'The slope of a velocity-time graph represents:','["acceleration", "force", "distance", "mass"]'::jsonb,0,'Slope of v-t is acceleration.','original'),
('127.401.d.8.E',4,'The area under a velocity-time graph gives:','["momentum", "displacement", "acceleration", "power"]'::jsonb,1,'Area equals velocity times time.','original'),
('127.401.d.8.F',3,'In projectile motion with no air resistance, the horizontal velocity:','["decreases to zero", "increases", "stays constant", "reverses"]'::jsonb,2,'No horizontal force acts.','original'),
('127.401.d.8.F',4,'A projectile reaches the highest point of its path when its vertical velocity is:','["negative", "equal to its horizontal velocity", "maximum", "zero"]'::jsonb,3,'It stops rising there.','original'),
('127.401.d.8.G',3,'Newton''s first law states that an object stays at rest or in uniform motion unless acted on by a:','["net external force", "small force", "color", "smaller mass"]'::jsonb,0,'Inertia resists changes in motion.','original'),
('127.401.d.8.G',4,'A book rests on a table. The net force on it is:','["its weight", "zero", "the table''s force", "infinite"]'::jsonb,1,'Weight and the normal force balance.','original'),
('127.401.d.8.H',3,'A free body diagram shows an object and all the:','["sounds it makes", "colors it has", "forces acting on it", "prices"]'::jsonb,2,'FBDs show forces as arrows.','original'),
('127.401.d.8.H',4,'A 10 kg crate is pushed with 50 N and friction of 20 N. The net force is:','["20 N", "70 N", "50 N", "30 N"]'::jsonb,3,'50 minus 20 is 30.','original'),
('127.401.d.8.I',3,'A rocket moves upward because gas pushed out the back produces a force on the rocket, which is an example of Newton''s:','["third law", "first law", "zeroth law", "fourth law"]'::jsonb,0,'Action and reaction pairs.','original'),
('127.401.d.8.I',4,'Increasing the mass of a toy rocket while its thrust stays the same will make its acceleration:','["unchanged", "smaller", "larger", "infinite"]'::jsonb,1,'a = F/m.','original'),
('127.401.d.8.J',3,'Newton''s law of universal gravitation says the force between two masses gets weaker as the distance between them:','["is constant", "decreases", "increases", "vanishes at once"]'::jsonb,2,'Force falls with the square of distance.','original'),
('127.401.d.8.J',4,'If the distance between two masses doubles, the gravitational force becomes:','["half as large", "four times larger", "twice as large", "one-fourth as large"]'::jsonb,3,'Inverse-square law.','original'),
('127.401.d.8.K',3,'Impulse is equal to the change in an object''s:','["momentum", "color", "mass", "volume"]'::jsonb,0,'Impulse equals force times time.','original'),
('127.401.d.8.K',4,'A crumple zone in a car reduces the force on passengers by increasing the:','["mass", "time of the collision", "speed", "friction on seats"]'::jsonb,1,'Longer time means smaller force for the same impulse.','original'),
('127.401.d.8.L',3,'Power is the rate at which:','["distance grows", "force is felt", "work is done or energy is transferred", "mass moves"]'::jsonb,2,'Power is work divided by time.','original'),
('127.401.d.8.L',4,'A motor does 600 J of work in 10 s. Its power is:','["6000 W", "610 W", "590 W", "60 W"]'::jsonb,3,'600 divided by 10.','original'),
('127.401.d.9.A',3,'Coulomb''s law says like charges:','["repel each other", "attract each other", "cancel", "have no force"]'::jsonb,0,'Same signs repel.','original'),
('127.401.d.9.A',4,'If the distance between two charges triples, the electric force becomes:','["three times as strong", "one-ninth as strong", "one-third as strong", "nine times as strong"]'::jsonb,1,'Inverse-square.','original'),
('127.401.d.9.B',3,'A generator converts mechanical energy into:','["sound only", "nuclear energy", "electrical energy", "food"]'::jsonb,2,'Generators induce current.','original'),
('127.401.d.9.B',4,'A transformer with more turns on its secondary coil than on its primary coil will:','["produce DC", "stop the current", "step down the voltage", "step up the voltage"]'::jsonb,3,'Voltage ratio follows turns ratio.','original'),
('127.401.d.9.C',3,'Copper wire is a conductor because it:','["allows charge to flow easily", "is heavy", "blocks charge", "is cold"]'::jsonb,0,'Conductors carry current.','original'),
('127.401.d.9.C',4,'Rubber is used on the outside of electrical cords because it is a good:','["fuel", "insulator", "conductor", "magnet"]'::jsonb,1,'Insulators block current.','original'),
('127.401.d.9.D',4,'If one bulb in a parallel circuit burns out, the other bulbs:','["go out", "get brighter only", "stay lit", "explode"]'::jsonb,2,'Each branch works independently.','original'),
('127.401.d.9.E',4,'A 12 V battery is connected to a 4 ohm resistor. The current is:','["0.33 A", "48 A", "8 A", "3 A"]'::jsonb,3,'I = V/R = 3.','original'),
('127.401.d.10.A',3,'A roller coaster at the top of a hill has the most:','["potential energy", "kinetic energy", "sound energy", "heat only"]'::jsonb,0,'Height gives potential energy.','original'),
('127.401.d.10.A',4,'As a pendulum swings down from its highest point, potential energy is converted into:','["mass", "kinetic energy", "volume", "charge"]'::jsonb,1,'Energy changes form.','original'),
('127.401.d.10.B',3,'Work is equal to force times:','["time", "speed", "distance", "mass"]'::jsonb,2,'W = Fd.','original'),
('127.401.d.10.B',4,'A 2 kg ball moving at 3 m/s has kinetic energy of:','["6 J", "12 J", "18 J", "9 J"]'::jsonb,3,'1/2 x 2 x 9 = 9.','original'),
('127.401.d.10.C',3,'A ramp is an example of an:','["inclined plane", "engine", "battery", "circuit"]'::jsonb,0,'Ramps are simple machines.','original'),
('127.401.d.10.C',4,'A seesaw is a(n):','["screw", "lever", "wedge", "pulley"]'::jsonb,1,'Seesaws pivot on a fulcrum.','original'),
('127.401.d.10.D',3,'The mechanical advantage of a machine is the ratio of the output force to the:','["mass", "time", "input force", "distance only"]'::jsonb,2,'MA = Fout / Fin.','original'),
('127.401.d.10.D',4,'A lever lifts a 200 N weight using an effort of 50 N. Its mechanical advantage is:','["0.25", "150", "250", "4"]'::jsonb,3,'200 divided by 50.','original'),
('127.401.d.10.E',3,'The law of conservation of energy says energy cannot be created or destroyed, only:','["changed from one form to another", "doubled", "made", "lost"]'::jsonb,0,'Total energy stays constant.','original'),
('127.401.d.10.E',4,'A 1 kg ball is dropped from 5 m (g = 10 m/s²). Just before landing, its kinetic energy is:','["10 J", "50 J", "5 J", "0.5 J"]'::jsonb,1,'mgh = 1 x 10 x 5 = 50.','original'),
('127.401.d.11.A',3,'The first law of thermodynamics states that energy is:','["created", "frozen", "conserved", "destroyed"]'::jsonb,2,'Energy is conserved.','original'),
('127.401.d.11.A',4,'The second law of thermodynamics says heat flows naturally from:','["big to small", "cold to hot", "dark to light", "hot objects to cold objects"]'::jsonb,3,'Heat spontaneously flows hot to cold.','original'),
('127.401.d.11.B',4,'The Sun warms the Earth mainly through:','["radiation", "conduction", "convection currents in space", "friction"]'::jsonb,0,'Radiation crosses empty space.','original'),
('127.401.d.11.C',3,'A thermos bottle is designed to:','["make heat", "minimize heat transfer", "increase heat transfer", "remove air flow in"]'::jsonb,1,'Insulation keeps contents warm or cold.','original'),
('127.401.d.11.C',4,'A heat sink on a computer chip is designed to:','["block air", "trap heat", "increase heat transfer away from the chip", "add heat"]'::jsonb,2,'Fins add surface area.','original'),
('127.401.d.12.A',3,'A pendulum''s swing back and forth is an example of:','["reflection", "rotation", "explosion", "oscillation"]'::jsonb,3,'Oscillation repeats.','original'),
('127.401.d.12.A',4,'For small angles, the period of a pendulum depends mainly on its:','["length", "bob material", "color", "mass"]'::jsonb,0,'T depends on length and gravity.','original'),
('127.401.d.12.B',3,'The time for one complete wave cycle is the:','["amplitude", "period", "speed", "wavelength"]'::jsonb,1,'Period is time per cycle.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
