select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_61_v1'
from (values
('127.401.d.12.B',4,'The distance between two consecutive crests of a wave is the:','["frequency", "amplitude", "wavelength", "period"]'::jsonb,2,'Crest to crest is wavelength.','original'),
