('127.402.d.1',3,'An engineer who discovers a safety flaw in a product that is already on sale should:','["hide it", "report it and work to correct it", "blame the user", "wait for a lawsuit"]'::jsonb,1,'Engineering ethics put public safety first.','original'),
('127.402.d.1',4,'A professional engineering code of ethics places highest priority on the:','["company logo", "speed of delivery", "safety, health, and welfare of the public", "engineer''s salary"]'::jsonb,2,'Public welfare comes first.','original'),
('127.402.d.2.A',3,'Defining the problem first in the engineering design process helps a team to:','["avoid research", "order parts", "pick colors", "know what the solution must accomplish"]'::jsonb,3,'A clear problem guides everything after it.','original'),
('127.402.d.2.A',4,'A team that skips defining the problem is most likely to:','["build something that does not meet the real need", "avoid all testing", "save money for sure", "finish early with a perfect result"]'::jsonb,0,'Unclear goals cause wasted effort.','original'),
('127.402.d.2.B',3,'During the research stage of design, a team gathers information about existing solutions and the:','["team jerseys", "needs of users", "price of lunch", "weather"]'::jsonb,1,'Research informs design.','original'),
('127.402.d.2.B',4,'Looking at what competing products already do well and poorly is called:','["manufacturing", "prototyping", "market or product research", "drafting"]'::jsonb,2,'Researching existing products reveals gaps.','original'),
('127.402.d.2.C',3,'Ideation is the stage in which a team:','["tests it", "ships it", "builds the final product", "generates many possible ideas"]'::jsonb,3,'Ideation means idea generation.','original'),
('127.402.d.2.C',4,'A concept sketch helps a team in conceptualization because it:','["turns an idea into something others can discuss", "removes risk", "eliminates cost", "replaces testing"]'::jsonb,0,'Sketches communicate concepts.','original'),
('127.402.d.2.D',3,'When choosing among concepts, a team should compare each against its:','["colors", "criteria and constraints", "random picks", "names"]'::jsonb,1,'Selection uses criteria.','original'),
('127.402.d.2.D',4,'A decision matrix helps a team to select a concept by:','["choosing the cheapest only", "flipping a coin", "scoring options against weighted criteria", "asking the loudest member"]'::jsonb,2,'Weighted scoring is objective.','original'),
('127.402.d.2.E',3,'A technical drawing is different from a nontechnical sketch because it follows:','["personal style only", "no rules", "random lines", "standard drawing conventions"]'::jsonb,3,'Technical drawings follow standards.','original'),
('127.402.d.2.E',4,'A physical model is built mainly to let a team:','["see and test the form of a design", "skip materials", "avoid drawings", "replace budgets"]'::jsonb,0,'Models make designs tangible.','original'),
('127.402.d.2.F',3,'Testing in the design process is used to find out whether a solution:','["is new", "meets its requirements", "looks nice", "is popular"]'::jsonb,1,'Tests check against criteria.','original'),
('127.402.d.2.F',4,'Collecting data during tests lets engineers:','["avoid changes", "ignore failures", "compare results with the design goals", "skip analysis"]'::jsonb,2,'Data supports decisions.','original'),
('127.402.d.2.G',3,'The engineering design process is iterative, which means steps are:','["skipped", "done in reverse only", "done once", "repeated as the design is improved"]'::jsonb,3,'Iteration refines designs.','original'),
('127.402.d.2.G',4,'Test results that show a flaw send the team back to an earlier step. This feedback loop shows that the process is:','["cyclical rather than strictly linear", "unnecessary", "finished", "random"]'::jsonb,0,'Design loops back.','original'),
('127.402.d.2.H',3,'Teams communicate throughout design so that everyone:','["keeps secrets", "understands goals, progress, and changes", "avoids notes", "works alone"]'::jsonb,1,'Communication keeps teams aligned.','original'),
('127.402.d.2.H',4,'The best way to share a change in the design with a distant teammate is to:','["tell no one", "change the plan later", "document it clearly and send it promptly", "wait until the end"]'::jsonb,2,'Prompt, clear documentation prevents errors.','original'),
('127.402.d.3.A',3,'Setting deadlines for each task helps a team to:','["skip tasks", "avoid planning", "start late", "finish a project on time"]'::jsonb,3,'Deadlines manage time.','original'),
('127.402.d.3.A',4,'Doing the most important and urgent tasks first is called:','["prioritizing", "guessing", "delaying", "procrastinating"]'::jsonb,0,'Priorities order the work.','original'),
('127.402.d.3.B',3,'A constraint on a design project can be a limit on:','["the team color", "budget, time, or materials", "the project name", "the printer brand"]'::jsonb,1,'Constraints restrict choices.','original'),
('127.402.d.3.B',4,'Planning around a constraint such as a fixed budget means the team should:','["request unlimited funds", "spend freely", "choose materials and methods that fit the budget", "ignore costs"]'::jsonb,2,'Plans must respect limits.','original'),
('127.402.d.3.C',3,'A milestone is a:','["final cost", "tool", "lunch break", "checkpoint marking progress in a project"]'::jsonb,3,'Milestones track progress.','original'),
('127.402.d.3.C',4,'Dividing a large project into smaller tasks makes it easier to:','["track progress and assign work", "avoid deadlines", "increase cost", "hide mistakes"]'::jsonb,0,'Smaller tasks are manageable.','original'),
('127.402.d.3.D',3,'An email is a written type of communication, while a face-to-face talk is:','["coded", "verbal", "silent", "written"]'::jsonb,1,'Spoken communication is verbal.','original'),
('127.402.d.3.D',4,'A short question that needs a quick answer is best sent by:','["a poster", "a letter by mail", "a chat message", "a formal report"]'::jsonb,2,'Match the format to the need.','original'),
('127.402.d.3.E',3,'A good first step in solving a problem is to:','["blame someone", "guess", "ignore it", "define it clearly"]'::jsonb,3,'Defining the problem guides action.','original'),
('127.402.d.3.E',4,'Breaking a problem into smaller parts to solve is a strategy known as:','["decomposition", "repetition", "avoidance", "delay"]'::jsonb,0,'Decompose complex problems.','original'),
('127.402.d.4.A',3,'Employers are responsible for providing a workplace that is:','["fun", "reasonably safe and free from known hazards", "rent-free", "always quiet"]'::jsonb,1,'Employers must provide safe workplaces.','original'),
('127.402.d.4.A',4,'Workers have the responsibility to follow safety rules and to:','["hide injuries", "ignore warnings", "report hazards and unsafe conditions", "skip training"]'::jsonb,2,'Workers help keep the site safe.','original'),
('127.402.d.4.B',3,'Industrial hygiene focuses on recognizing and controlling workplace:','["pay rates", "vacations", "uniforms", "health hazards"]'::jsonb,3,'Industrial hygienists protect worker health.','original'),
('127.402.d.4.B',4,'Measuring noise, dust, and chemical levels at a plant is the work of:','["industrial hygiene", "sales", "marketing", "payroll"]'::jsonb,0,'Hygiene measures exposures.','original'),
('127.402.d.4.C',3,'Hearing protection is worn to protect the ears from:','["cold", "loud noise", "wind", "bright light"]'::jsonb,1,'Earplugs and muffs reduce noise.','original'),
('127.402.d.4.C',4,'The best personal protective equipment for grinding metal includes:','["sunglasses only", "bare hands", "safety glasses or a face shield", "sandals"]'::jsonb,2,'Sparks require eye and face protection.','original'),
('127.402.d.4.D',3,'To prevent trips in a shop, walkways should be kept:','["dark", "narrow", "wet", "clear of cords and clutter"]'::jsonb,3,'Clear paths prevent falls.','original'),
('127.402.d.4.D',4,'A spill on a shop floor should be:','["cleaned up immediately or marked with a warning sign", "ignored", "left until later", "walked around quickly"]'::jsonb,0,'Wet floors cause slips.','original'),
('127.402.d.4.E',3,'Water and electricity together are dangerous because water:','["stops current", "conducts electricity", "blocks it", "absorbs it harmlessly"]'::jsonb,1,'Water creates shock paths.','original'),
('127.402.d.4.E',4,'A ground fault circuit interrupter (GFCI) protects people by:','["blocking all current", "increasing voltage", "shutting off power when it detects leakage current", "cooling wires"]'::jsonb,2,'GFCIs trip quickly.','original'),
('127.402.d.4.F',3,'An emergency action plan includes exit routes and:','["uniform colors", "menu choices", "sale prices", "assembly points"]'::jsonb,3,'Everyone should know where to go.','original'),
('127.402.d.4.F',4,'Safety Data Sheets are a workplace resource that provide information on a chemical''s:','["hazards and safe handling", "color", "price", "owner"]'::jsonb,0,'SDS describe hazards.','original'),
('127.402.d.5.A',3,'An engineering notebook is valuable because it can serve as a:','["game log", "legal record of ideas and work", "grocery list", "music diary"]'::jsonb,1,'Notebooks help prove dates of invention.','original'),
('127.402.d.5.A',4,'Entries in an engineering notebook should be dated and signed so the notebook can:','["be erased easily", "be hidden", "help prove who invented something and when", "replace patents"]'::jsonb,2,'Dates and signatures establish authorship.','original'),
('127.402.d.5.B',3,'In an engineering notebook, mistakes should be:','["erased fully", "torn out", "covered in correction fluid", "crossed out with a single line"]'::jsonb,3,'Original entries must remain visible.','original'),
('127.402.d.5.B',4,'Pages in a bound engineering notebook are numbered so that:','["missing pages can be detected", "ink is saved", "covers match", "pages look nicer"]'::jsonb,0,'Numbered pages protect integrity.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_61_v1'
from (values
('127.402.d.5.C',3,'A notebook entry should include sketches, notes, and:','["jokes", "data and observations", "unrelated drawings", "gossip"]'::jsonb,1,'Record what you did and saw.','original'),
